downloadSVG.handler:
function downloadSVG(args, ctx) {
  const blob = new Blob([args.content], { type: 'image/svg+xml' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = args.filename.endsWith('.svg') ? args.filename : `${args.filename}.svg`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}
